    descriptionAdvanced: {
      de: "Das Museum der Schönen Künste (MBA) in Caracas ist die älteste Museumsinstitution Venezuelas, gegründet im Jahr 1917. Es befindet sich im Kulturviertel des Los Caobos-Parks und besteht aus zwei architektonisch unterschiedlichen Gebäuden. Das erste ist ein neoklassizistisches Gebäude, das von dem renommierten Architekten Carlos Raúl Villanueva entworfen und 1938 eingeweiht wurde; es verfügt über einen wunderschönen Innenhof mit Skulpturen. Das zweite ist ein modernistisches, brutalistisches Gebäude, ebenfalls von Villanueva entworfen, das 1976 eröffnet wurde, um mehr Platz für die wachsende Sammlung zu bieten. Das Erbe des Museums umfasst über 5.000 Kunstwerke, die von altägyptischen Artefakten und chinesischer Keramik bis hin zu europäischen Meistern und modernen lateinamerikanischen Künstlern reichen. Es dient als wichtiges Zentrum für kunsthistorische Forschung, Konservierung und Bildung im Land. Das MBA veranstaltet regelmäßig Wechselausstellungen und Workshops und ist seit über einem Jahrhundert ein Eckpfeiler des venezolanischen Kulturlebens.",
      hu: "A caracasi Szépművészeti Múzeum (MBA) Venezuela legrégebbi múzeumi intézménye, amelyet 1917-ben alapítottak. A Los Caobos park kulturális negyedében található, és két elkülönülő építészeti egységből áll. Az első egy neoklasszicista épület, amelyet a neves építész, Carlos Raúl Villanueva tervezett és 1938-ban adtak át, gyönyörű szobrokkal díszített belső udvarral. A második egy modernista, brutalista épület, szintén Villanueva tervei alapján, amely 1976-ben nyílt meg a növekvő gyűjtemény befogadására. A múzeum öröksége több mint 5000 műalkotást tartalmaz, az ókori egyiptomi tárgyaktól és kínai kerámiáktól kezdve európai mesterek művein át a modern latin-amerikai művészekig. Fontos központja a művészettörténeti kutatásnak, a konzerválásnak és az oktatásnak az országban. Az MBA rendszeresen ad otthont időszaki kiállításoknak és műhelyfoglalkozásoknak, több mint egy évszázada a venezuelai kulturális élet sarokköve maradva.",
      ro: "Muzeul de Arte Frumoase (MBA) din Caracas este cea mai veche instituție muzeală din Venezuela, fondată în 1917. Este situat în cartierul cultural al Parcului Los Caobos și constă din două structuri arhitecturale distincte. Prima este o clădire neoclasică proiectată de renumitul arhitect Carlos Raúl Villanueva și inaugurată în 1938, având o curte interioară frumoasă cu sculpturi. Cea de-a doua este o clădire modernistă, brutalistă, proiectată tot de Villanueva, care s-a deschis în 1976 pentru a oferi mai mult spațiu colecției în creștere. Patrimoniul muzeului include peste 5.000 de opere de artă, variind de la artefacte egiptene antice și ceramică chineză până la maeștri europeni și artiști moderni latino-americani. Acesta servește ca un centru major pentru cercetarea istoriei artei, conservare și educație în țară. MBA găzduiește frecvent expoziții temporare și ateliere, menținându-și rolul de piatră de temelie a vieții culturale venezuelene de peste un secol.",
      en: "The Museum of Fine Arts (MBA) in Caracas is the oldest museum institution in Venezuela, founded in 1917. It is situated in the cultural district of Los Caobos Park and consists of two distinct architectural structures. The first is a neoclassical building designed by Carlos Raúl Villanueva and inaugurated in 1938, featuring a beautiful central courtyard with sculptures. The second is a modernist, brutalist building, also designed by Villanueva, which opened in 1976 to provide more space for the growing collection. The museum's heritage includes over 5,000 works of art, ranging from ancient Egyptian artifacts and Chinese ceramics to European masters and modern Latin American artists. It serves as a major center for artistic research, conservation, and education in the country. The MBA frequently hosts temporary exhibitions and workshops, maintaining its role as a cornerstone of Venezuelan cultural life and art history education for over a century.",
      es: "El Museo de Bellas Artes (MBA) en Caracas es una institución de talla mundial. Se encuentra en un elegante edificio neoclásico al que se añadió posteriormente una ampliación moderna, reflejando la evolución arquitectónica de la ciudad. Las colecciones abarcan obras desde la antigüedad hasta la modernidad, con especial énfasis en el arte latinoamericano. El museo es un centro de educación cultural y ofrece una visión profunda de la riqueza estética de la historia de la humanidad. Arte K7 — Museología.",
      pt: "O Museu de Belas Artes (Museo de Bellas Artes) em Caracas é uma instituição de classe mundial. Está instalado num elegante edifício neoclássico que foi mais tarde complementado por uma extensão moderna, refletindo a evolução arquitetónica da cidade. As coleções abrangem obras desde a antiguidade até à modernidade, com um foco especial na arte latino-americana. O museu é um centro de educação cultural e oferece uma visão profunda da riqueza estética da história da humanidade. Arte K7 — Museologia.",
      fr: "Le Musée des Beaux-Arts (Museo de Bellas Artes) de Caracas est une institution de classe mondiale. Il est installé dans un élégant bâtiment néoclassique auquel a été ajoutée plus tard une extension moderne, reflétant l'évolution architecturale de la ville. Les collections comprennent des œuvres de l'Antiquité à l'époque moderne, avec un accent particulier sur l'art latino-américain. Le musée est un centre d'éducation culturelle et offre un aperçu profond de la richesse esthétique de l'histoire de l'humanité. Art K7 — Muséologie.",
    },
