      hu: ["1982. augusztus 7-én nyitotta meg Alicia Pietri de Caldera.", "Ez volt az első interaktív gyermekmúzeum Latin-Amerikában.", "A caracasi Parque Central komplexum alsó szintjein található.", "Hivatalos mottója: 'Játssva tanulni'.", "Modern planetáriumot és űrkutatási csarnokot foglal magában.", "Interaktív állomásokat kínál a fizika, biológia és kémia témakörében."],
      ro: ["Inaugurat la 7 august 1982 de către Alicia Pietri de Caldera.", "A fost primul muzeu interactiv pentru copii din America Latină.", "Este situat la nivelurile inferioare ale complexului Parque Central.", "Motto-ul oficial este 'A învăța jucându-te'.", "Adăpostește un planetariu modern și o sală de explorare spațială.", "Oferă stații interactive despre fizică, biologie și chimie."],
      en: ["Opened on August 7, 1982, by Alicia Pietri de Caldera.", "It was the first interactive children's museum in Latin America.", "Located in the lower levels of the Parque Central complex.", "The official motto is 'Learning by playing'.", "It houses a modern planetarium and a space exploration hall.", "Offers interactive stations on physics, biology, and chemistry."],
      es: ["El museo abrió en 1982 y desde entonces ha marcado a generaciones de niños venezolanos.", "Las exposiciones cubren áreas temáticas como el espacio, la ecología y la comunicación.", "Se encuentra en un edificio emblemático en el centro de la ciudad.", "El concepto interactivo ha sido reconocido internacionalmente por su calidad pedagógica."],
      pt: ["O museu foi inaugurado em 1982 e desde então marcou gerações de crianças venezuelanas.", "As exposições abrangem áreas temáticas como o espaço, a ecologia e a comunicação.", "Situa-se num edifício marcante no centro da cidade.", "O conceito interativo foi premiado internacionalmente pela sua qualidade pedagógica."],
      fr: ["Le musée a ouvert ses portes en 1982 et a depuis marqué des générations d'enfants vénézuéliens.", "Les expositions couvrent des domaines tels que l'espace, l'écologie et la communication.", "Il est situé dans un bâtiment remarquable au centre de la ville.", "Le concept interactif a été récompensé au niveau international pour sa qualité pédagogique."],
