      hu: ["Korábban ferences kolostor (Convento de San Francisco)", "Neogótikus stílusú átalakítás 1872-től", "Hat nemzeti akadémia székhelye", "1956 óta nemzeti történelmi műemlék", "Itt található az Akadémiai Könyvtár", "Juan Hurtado Manrique építész vezette az átalakítást"],
      ro: ["Fostă mănăstire franciscană (Convento de San Francisco)", "Remodelare în stil neogotic începând cu 1872", "Sediul a șase academii naționale", "Monument istoric național din 1956", "Găzduiește Biblioteca Academiei", "Arhitectul Juan Hurtado Manrique a condus lucrările"],
