      es: ["El edificio ha cumplido diversas funciones a lo largo de los siglos, desde convento hasta universidad.", "La transformación neogótica tuvo lugar a finales del siglo XIX.", "Alberga las academias de Historia, Lengua, Medicina y Ciencias Físicas y Naturales.", "El palacio es una parte importante del patrimonio histórico y arquitectónico de Caracas."],
      pt: ["O edifício desempenhou várias funções ao longo dos séculos, de convento a universidade.", "A transformação neogótica ocorreu no final do século XIX.", "Abriga as academias de História, Língua, Medicina e Ciências Naturais.", "O palácio é uma parte importante do patrimônio histórico e arquitetônico de Caracas."],
      fr: ["Le bâtiment a rempli diverses fonctions au cours des siècles, de couvent à université.", "La transformation néogothique a eu lieu à la fin du XIXe siècle.", "Il abrite les académies d'histoire, de langue, de médecine et des sciences naturelles.", "Le palais est un élément important du patrimoine historique et architectural de Caracas."],
