      hu: ["Az 1811-es függetlenségi nyilatkozat helyszíne", "A Santa Rosa szeminárium romjaira épült", "Itt található a Caracasi Múzeum", "1979 óta nemzeti történelmi műemlék", "Juan Hurtado Manrique építész tervezte", "A híres Santa Rosa-kápolna otthona"],
      ro: ["Locul semnării Declarației de Independență din 1811", "Construit pe ruinele Seminarului Santa Rosa", "Găzduiește Muzeul din Caracas", "Monument istoric național din 1979", "Arhitectul Juan Hurtado Manrique a proiectat palatul", "Locația celebrei Capele Santa Rosa"],
