      es: ["El edificio fue renovado integralmente a finales del siglo XIX para conservar su carácter actual.", "En la 'Capilla de Santa Rosa de Lima' dentro del palacio se firmó el Acta de Independencia.", "El Museo de la Ciudad muestra fascinantes miniaturas de Caracas de diferentes épocas.", "El palacio es la sede del Concejo Municipal y, por tanto, el corazón administrativo del municipio Libertador."],
      pt: ["O edifício foi amplamente renovado no final do século XIX para manter seu caráter atual.", "Na 'Capela de Santa Rosa de Lima' dentro do palácio, foi assinada a declaração de independência.", "O Museu da Cidade mostra miniaturas fascinantes de Caracas de diferentes épocas.", "O palácio é a sede do Conselho Municipal e, portanto, o coração administrativo do município Libertador."],
      fr: ["Le bâtiment a été entièrement rénové à la fin du XIXe siècle pour conserver son caractère actuel.", "Dans la 'Chapelle de Santa Rosa de Lima' à l'intérieur du palais, la déclaration d'indépendance a été signée.", "Le Musée de la Ville présente de fascinantes miniatures de Caracas à différentes époques.", "Le palais est le siège du Conseil municipal et donc le cœur administratif de la municipalité de Libertador."],
