    image: "/poi-images/venezuela-correo-de-carmelitas-landmark-v2.webp",
    description: {
      de: "Ein markantes Gebäude in der Innenstadt von Caracas, das für seine elegante neoklassizistische Fassade bekannt ist.",
      hu: "Jellegzetes épület Caracas belvárosában, amely elegáns neoklasszicista homlokzatáról ismert.",
      ro: "O clădire distinctivă în centrul orașului Caracas, cunoscută pentru fațada sa neoclasică elegantă.",
      en: "A striking building in downtown Caracas, known for its elegant neoclassical facade.",
      es: "Un edificio emblemático en el centro de Caracas, conocido por su elegante fachada neoclásica.",
      pt: "Um edifício emblemático no centro de Caracas, conhecido pela sua elegante fachada neoclássica.",
      fr: "Un bâtiment emblématique du centre-ville de Caracas, connu pour son élégante façade néoclassique.",
    },
    descriptionAdvanced: {
      de: "Das Correo de Carmelitas ist ein markantes historisches Gebäude in Caracas, das als Hauptsitz des venezolanischen Postdienstes bekannt ist. Seine Geschichte reicht bis ins Jahr 1781 zurück, als es ursprünglich als Herrenhaus für den Grafen von Tovar erbaut wurde. Im Laufe der Jahrhunderte diente es verschiedenen Zwecken, darunter als Sitz der Präsidentschaft und als Kriegsministerium. Die heutige Architektur im neoklassizistischen Stil mit gotischen Einflüssen ist das Ergebnis einer umfassenden Renovierung in den 1930er Jahren. Das Gebäude ist nach dem ehemaligen Kloster der Karmelitinnen benannt, das sich früher in der Nähe befand. Die markante Ecklage an der Avenida Urdaneta macht es zu einem der bekanntesten Wahrzeichen im Stadtzentrum. Im Inneren finden sich kunstvolle Details und Schalterhallen, die an die Blütezeit der Postkommunikation erinnern. Es steht als geschütztes Denkmal für die institutionelle Kontinuität und den architektonischen Wandel von Caracas über drei Jahrhunderte.",
      hu: "A Correo de Carmelitas Caracas egyik jellegzetes történelmi épülete, amely a venezuelai postaszolgálat központjaként ismert. Története 1781-ig nyúlik vissza, amikor eredetileg Tovar grófjának kúriájaként épült. Az évszázadok során különböző célokat szolgált, többek között elnöki székhelyként és hadügyminisztériumként is működött. A jelenlegi, neoklasszicista stílusú, gótikus hatásokkal tarkított építészet az 1930-as években végzett átfogó felújítás eredménye. Az épület a közelben egykoron elhelyezkedő karmelita kolostorról kapta a nevét. Az Avenida Urdaneta sarkán elfoglalt hangsúlyos elhelyezkedése a városközpont egyik legismertebb jelképévé teszi. Belsejében művészi részletek és ügyfélterek találhatók, amelyek a postai kommunikáció fénykorát idézik. Védett műemlékként Caracas intézményi folytonosságának és három évszázadon átívelő építészeti változásának tanúja.",
      ro: "Correo de Carmelitas este o clădire istorică distinctivă din Caracas, cunoscută ca sediul central al serviciului poștal venezuelean. Istoria sa datează din 1781, când a fost construită inițial ca reședință pentru Contele de Tovar. De-a lungul secolelor, a servit diverse scopuri, inclusiv sediul președinției și Ministerul de Război. Arhitectura actuală în stil neoclasic cu influențe gotice este rezultatul unei renovări majore din anii 1930. Clădirea poartă numele fostei mănăstiri a Carmeliților, care se afla în apropiere. Amplasarea sa proeminentă pe colț, la intersecția cu Avenida Urdaneta, o face unul dintre cele mai recunoscute repere din centrul orașului. În interior se găsesc detalii artistice și ghișee care amintesc de epoca de aur a comunicării poștale. Este un monument protejat care stă mărturie pentru continuitatea instituțională și transformarea arhitecturală a orașului Caracas de-a lungul a trei secole.",
      en: "The Carmelitas Post Office is a distinctive historic building in Caracas, widely known as the headquarters of the Venezuelan postal service. Its history dates back to 1781 when it was originally built as a mansion for the Count of Tovar. Over the centuries, it has served various purposes, including being the seat of the Presidency and the Ministry of War. The current neoclassical architecture with Gothic influences is the result of a major renovation carried out in the 1930s. The building is named after the former Carmelite convent that used to be located nearby. Its prominent corner location on Avenida Urdaneta makes it one of the most recognizable landmarks in the city center. Inside, artistic details and teller halls evoke the heyday of postal communication. It stands as a protected monument testifying to the institutional continuity and architectural evolution of Caracas across three centuries.",
      es: "El Palacio de las Carmelitas es un hito arquitectónico en el centro de Caracas. Originalmente una residencia señorial, fue convertido a principios del siglo XX en un magnífico edificio de correos. Su elegante fachada neoclásica y sus finos detalles arquitectónicos son testimonio de la prosperidad civil de aquella época. Representa la etapa en la que Caracas se modernizó y los servicios públicos se alojaron en construcciones monumentales. Arquitectura K7 — Paisaje Urbano.",
      pt: "O Correo de Carmelitas é um marco arquitetónico no centro de Caracas. Originalmente uma residência senhorial, foi convertido no início do século XX num magnífico edifício de correios. A sua elegante fachada neoclássica e os finos detalhes arquitetónicos são um testemunho da prosperidade civil da época. Representa a era em que Caracas foi modernizada e os serviços públicos foram instalados em edifícios monumentais. Arquitetura K7 — Paisagem Urbana.",
      fr: "La Poste de Carmelitas est un monument architectural du centre de Caracas. À l'origine une demeure seigneuriale, elle a été transformée au début du XXe siècle en un magnifique bâtiment postal. Son élégante façade néoclassique et ses fins détails architecturaux témoignent de la prospérité civile de l'époque. Elle représente la période de modernisation de Caracas, où les services publics étaient installés dans des édifices monumentaux. Architecture K7 — Paysage Urbain.",
    },
