      pt: ["As torres foram projetadas pelo arquiteto Cipriano Domínguez.", "Foram, durante décadas, as estruturas mais altas da Venezuela.", "O projeto marcou o fim das estruturas coloniais no atual bairro de El Silencio.", "As torres gémeas são um exemplo notável do Estilo Internacional na América do Sul."],
      fr: ["Les tours ont été conçues par l'architecte Cipriano Domínguez.", "Elles ont été pendant des décennies les structures les plus hautes du Venezuela.", "Le projet a marqué la fin du bâti colonial dans l'actuel quartier d'El Silencio.", "Les tours jumelles sont un exemple remarquable du style international en Amérique du Sud."],
