      hu: ["Az ikertornyok magassága: 225 méter", "Építési ideje: 1970-től 1983-ig", "Latin-Amerika legmagasabb épületei 2003-ig", "Tűzvész a Keleti Toronyban: 2004. október 17.", "A Kortárs Művészeti Múzeum székhelye", "8 lakóblokkból és 2 irodatoronyból áll"],
      ro: ["Înălțimea turnurilor gemene: 225 de metri", "Perioada de construcție: 1970-1983", "Cele mai înalte clădiri din America Latină până în 2003", "Incendiu în Turnul de Est la 17 octombrie 2004", "Găzduiește Muzeul de Artă Contemporană", "Compus din 8 blocuri rezidențiale și 2 turnuri de birouri"],
      en: ["Height of the twin towers: 225 meters", "Construction period: 1970 to 1983", "Tallest buildings in Latin America until 2003", "Major fire in the East Tower on October 17, 2004", "Houses the Museum of Contemporary Art", "Consists of 8 residential blocks and 2 office towers"],
      es: ["El complejo alberga museos importantes como el Museo de Arte Contemporáneo.", "Las torres alcanzan una altura de más de 220 metros.", "Parque Central fue un proyecto pionero de megaestructuras multifuncionales en Sudamérica.", "Las plataformas de observación ofrecen una vista panorámica espectacular de todo el valle de Caracas."],
