    descriptionAdvanced: {
      de: "Das Monumento a la Virgen de la Paz ist eine kolossale Gedenkstatue zu Ehren Mariens, die sich auf einem Hügel in der Nähe von Trujillo in Venezuela befindet. Mit einer Höhe von 46,72 Metern war sie bei ihrer Einweihung am 21. Dezember 1983 die höchste Marienstatue der Welt und übertrifft sogar die Freiheitsstatue in New York und die Christus-Erlöser-Statue in Rio de Janeiro. Die Skulptur wurde vom Künstler Manuel de la Fuente entworfen und besteht vollständig aus Beton, wobei sie etwa 1.200 Tonnen wiegt. Besucher können das Innere der Statue besteigen, wobei fünf verschiedene Aussichtsplattformen spektakuläre Ausblicke über den Bundesstaat Trujillo bis hin zum Maracaibo-See bieten. Das Denkmal steht auf der Peña de la Virgen, einem Ort, an dem Maria im Jahr 1570 erschienen sein soll. Es dient heute als bedeutendes religiöses Zentrum und Symbol für den Frieden in der Region und zieht jährlich Tausende von Pilgern und Touristen an.",
      hu: "A Monumento a la Virgen de la Paz (Béke Szűz emlékmű) egy kolosszális fogadalmi szobor, amely a venezuelai Trujillo városának közelében található egy dombtetőn. A 46,72 méter magas alkotást 1983. december 21-én avatták fel, és ekkor a világ legmagasabb Mária-szobraként tartották számon, megelőzve magasságban a New York-i Szabadság-szobrot és a Rio de Janeiro-i Megváltó Krisztus-szobrot is. A Manuel de la Fuente szobrászművész által tervezett alkotás teljes egészében betonból készült, súlya megközelíti az 1200 tonnát. A szobor belsejében lépcsősor vezet felfelé, amely öt különböző kilátópontot érint, ahonnan tiszta időben egészen a Maracaibo-tóig el lehet látni. Az emlékmű a Peña de la Virgen sziklán áll, ahol a hagyomány szerint 1570-ben megjelent a Szűzanya. Ez a vallási helyszín mára Venezuela egyik legfontosabb zarándokhelyévé és a régió békéjének jelképévé vált.",
      ro: "Monumento a la Virgen de la Paz este o statuie colosală dedicată Fecioarei Maria, situată pe un deal în apropierea orașului Trujillo din Venezuela. Având o înălțime de 46,72 metri, monumentul a fost inaugurat la 21 decembrie 1983 și a deținut mult timp recordul pentru cea mai înaltă statuie a Fecioarei Maria din lume, depășind în dimensiuni Statuia Libertății din New York. Opera a fost concepută de sculptorul Manuel de la Fuente și este realizată integral din beton, cântărind aproximativ 1.200 de tone. Structura interioară permite vizitatorilor să urce până la cinci platforme de observație diferite, oferind panorame spectaculoase asupra statului Trujillo și, în condiții meteorologice favorabile, până la Lacul Maracaibo. Monumentul este amplasat pe stânca Peña de la Virgen, locul unde legenda spune că Fecioara Maria s-a arătat în anul 1570. Astăzi, obiectivul reprezintă un important punct de pelerinaj religios și un simbol al păcii universale.",
      en: "The Monumento a la Virgen de la Paz is a colossal commemorative statue honoring Mary, located on a hill near Trujillo in Venezuela. Standing at 46.72 meters tall, it was the tallest statue of Mary in the world upon its inauguration on December 21, 1983, even surpassing the height of the Statue of Liberty and Christ the Redeemer. Designed by sculptor Manuel de la Fuente, the structure is made entirely of concrete and weighs approximately 1,200 tons. Visitors can climb inside the statue to reach five different observation levels, which offer breathtaking views of the state of Trujillo and, on clear days, as far as Lake Maracaibo. The monument is situated on the Peña de la Virgen, the site where Mary is said to have appeared in 1570. It serves as a major religious landmark and a symbol of peace, attracting thousands of pilgrims and tourists each year who come to appreciate its architectural scale and spiritual significance.",
      es: "El Monumento a la Paz en Trujillo es una colosal estatua de María, visible mucho más allá de la región andina. Con su impresionante altura, es uno de los monumentos religiosos más altos del hemisferio occidental. Los visitantes pueden subir al interior de la estatua y disfrutar de vistas impresionantes de las montañas de Trujillo desde varios miradores. El monumento es un símbolo de la profunda fe y el deseo de paz en Venezuela. Religión K6 — Escultura Monumental.",
      pt: "O Monumento à Paz (Monumento a la Paz) em Trujillo é uma estátua colossal de Maria, visível muito para além da região andina. Com a sua altura impressionante, é um dos monumentos religiosos mais altos do hemisfério ocidental. Os visitantes podem subir ao interior da estátua e desfrutar de vistas deslumbrantes sobre as montanhas de Trujillo a partir de vários miradouros. O monumento é um símbolo da fé profunda e do desejo de paz na Venezuela. Religião K6 — Escultura Monumental.",
      fr: "Le Monument à la Paix (Monumento a la Paz) à Trujillo est une statue colossale de Marie, visible bien au-delà de la région andine. Avec sa hauteur impressionnante, c'est l'un des monuments religieux les plus hauts de l'hémisphère occidental. Les visiteurs peuvent monter à l'intérieur de la statue et profiter d'une vue imprenable sur les montagnes de Trujillo depuis plusieurs plateformes d'observation. Le monument est un symbole de la foi profonde et du désir de paix au Venezuela. Religion K6 — Sculpture Monumentale.",
    },
