      hu: ["A szobor magassága 46,72 méter, ami meghaladja a Szabadság-szobor alakjának magasságát.", "Az emlékművet 1983. december 21-én avatták fel Trujillo mellett.", "A szerkezet össztömege körülbelül 1200 tonna betonból áll.", "Öt kilátóterasz található benne, a legmagasabb a szobor szeménél helyezkedik el.", "A tengerszint feletti magassága 1600 méter a Peña de la Virgen dombon.", "Manuel de la Fuente szobrászművész tervezte és felügyelte az építkezést."],
