      pt: ["O monumento atinge uma altura de cerca de 46,7 metros.", "Foi inaugurado em 1983 e é um local de peregrinação importante.", "A estátua é acessível por dentro e possui cinco pontos de observação.", "É considerada a estátua da Virgem Maria mais alta de toda a América."],
